  `channel_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  `local_refunded` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  `channel_refunded` DECIMAL(10,2) NOT NULL DEFAULT 0.00,
